from scipy.optimize import least_squares
t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
fs={'sin':lambda w:np.sin(w*t),'cos':lambda w:np.cos(w*t),'expm':lambda w:np.exp(-w*t),'exp+':lambda w:np.exp(w*t/10),'tw':lambda w: t**w}
rs=np.random.RandomState(1)
for name,f in fs.items():
  for withconst in [True,False]:
    def m(p):
        out=p[0]*t**2 + p[1]*(t/(1+p[2]*t))*A**2 + p[4]*A**p[5]*f(p[6])
        if withconst: out=out+p[3]
        return out
    best=None
    for s in range(40):
        p0=np.r_[rs.randn(2), abs(rs.randn())+0.5, rs.randn(), rs.randn(), rs.uniform(0,3), abs(rs.uniform(0.2,3))]
        try: r=least_squares(lambda p: m(p)-y, p0, max_nfev=500)
        except Exception: continue
        if not np.all(np.isfinite(r.fun)): continue
        if best is None or r.cost<best.cost: best=r
    print(name,withconst, np.round(best.x,3), np.mean((y-m(best.x))**2)/np.var(y))

